"""Strict character controls generated by Qwen, never raw SVG markup.

Rig joints and anatomy always come from trusted mascot_v1 SVG artwork.
"""
from __future__ import annotations

import json
from pathlib import Path
from typing import Literal

from pydantic import BaseModel, ConfigDict

PALETTES = {
    "charcoal": {"ink": "#20232B", "accent": "#EF7559", "face": "#FFFCF4",
                 "detail": "#41454D", "shade": "#252B33"},
    "navy": {"ink": "#243752", "accent": "#53A7DC", "face": "#FFFDF6",
             "detail": "#53647E", "shade": "#243752"},
    "plum": {"ink": "#34253D", "accent": "#DD81A4", "face": "#FFF9F2",
             "detail": "#6C526F", "shade": "#34253D"},
    "forest": {"ink": "#234339", "accent": "#63BFA0", "face": "#FFFDF6",
               "detail": "#5E7769", "shade": "#234339"},
    "sunset": {"ink": "#4B2D32", "accent": "#F38C57", "face": "#FFF8EE",
               "detail": "#866064", "shade": "#4B2D32"},
}
PALETTE_IDS = tuple(PALETTES)
EXPRESSIONS = ("happy", "surprised", "curious", "thoughtful", "confident")
EYES = ("friendly", "wide", "relaxed")
BROWS = ("soft", "raised", "focused")
CHEEKS = ("none", "subtle")
ACCENTS = ("coral", "simple", "none")


class CharacterSpec(BaseModel):
    """All required, bounded design attributes. Joint positions are forbidden."""

    model_config = ConfigDict(extra="forbid", strict=True)

    version: Literal[1]
    palette: Literal["charcoal", "navy", "plum", "forest", "sunset"]
    expression: Literal["happy", "surprised", "curious", "thoughtful", "confident"]
    eyes: Literal["friendly", "wide", "relaxed"]
    brows: Literal["soft", "raised", "focused"]
    cheeks: Literal["none", "subtle"]
    accent: Literal["coral", "simple", "none"]


DEFAULT_SPEC = CharacterSpec(
    version=1, palette="charcoal", expression="happy",
    eyes="friendly", brows="soft", cheeks="subtle", accent="coral"
)

SYSTEM_PROMPT = (
    "You are a 2D character art director. Translate the requested mascot look into "
    "ONLY one compact JSON object without markdown. Required keys: "
    "version=1; palette: charcoal/navy/plum/forest/sunset; "
    "expression: happy/surprised/curious/thoughtful/confident; "
    "eyes: friendly/wide/relaxed; brows: soft/raised/focused; "
    "cheeks: none/subtle; accent: coral/simple/none. "
    "Use exactly these keys and supported values. Never output SVG, code, limbs, "
    "joint coordinates, hats, background paths, or extra fields. "
    "The trusted vector rig handles every body part and gesture."
)


def parse_spec(data: str | dict | CharacterSpec) -> CharacterSpec:
    if isinstance(data, CharacterSpec):
        return data
    if isinstance(data, str):
        if len(data) > 4096:
            raise ValueError("Character spec exceeds 4096 characters")
        data = json.loads(data)
    return CharacterSpec.model_validate(data)


def load_spec(path: str | Path) -> CharacterSpec:
    return parse_spec(Path(path).read_text(encoding="utf-8"))


def save_spec(spec: CharacterSpec | dict, path: str | Path) -> Path:
    validated = parse_spec(spec)
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(validated.model_dump_json(indent=2), encoding="utf-8")
    return path
